module barrel_shifter (
    input [7:0] in,
    input [2:0] ctrl,
    output [7:0] out
);

wire [7:0] mux_out_1, mux_out_2;

assign mux_out_1 = (ctrl[2]) ? {in[3:0], 4'b0} : in;

assign mux_out_2 = (ctrl[1]) ? {mux_out_1[5:0], 2'b0} : mux_out_1;

assign out = (ctrl[0]) ? {mux_out_2[6:0], 1'b0} : mux_out_2;

endmodule

module mux2X1( in0,in1,sel,out);
input in0,in1;
input sel;
output out;
assign out=(sel)?in1:in0;
endmodule
